const experiments = $('Load Experiment Feed').item.json;
const started = $('Start Patch Training').item.json;
const config = $('Build CRC Patch Config').item.json;
const latest = Array.isArray(experiments) ? experiments.find((item) => item.experiment_id === started.experiment_id) || experiments[0] : null;
const metrics = latest?.metrics || {};
const history = Array.isArray(metrics.history) ? metrics.history : [];
return [{ json: { ok: true, workflow: 'Timestamp_msi CRC patch training loop', startedAt: config.startedAt, experimentId: started.experiment_id, experimentName: latest?.name || config.experimentName, status: latest?.status || 'unknown', datasetPath: config.datasetPath, backbone: metrics.backbone || config.backbone, accuracy: metrics.best_val_accuracy ?? null, macroF1: metrics.final_val_f1_macro ?? null, auroc: metrics.val_auroc_ovr_macro ?? null, epochsTracked: history.length, latestEpoch: history.length ? history[history.length - 1] : null, modelPath: metrics.artifacts?.model_path || null, next: latest?.status === 'running' ? 'Keep this workflow active on a schedule or repeat the refresh block until the status becomes completed.' : 'Run again with a new backbone or epoch count to compare patch models.' } }];
